    <script>
        (() => {
            const tabs = ['general', 'email', 'branding', 'social', 'cookie', 'extensions'];
            const buttons = document.querySelectorAll('[data-settings-tab]');
            const panels = document.querySelectorAll('[data-settings-panel]');
            const initial = @json($activeTab);
            const activate = (name, updateHash = true) => {
                if (!tabs.includes(name)) name = 'general';
                buttons.forEach((button) => {
                    const active = button.dataset.settingsTab === name;
                    button.classList.toggle('border-b-2', active);
                    button.classList.toggle('border-[#7668f6]', active);
                    button.classList.toggle('text-[#7668f6]', active);
                    button.classList.toggle('text-[#7b879a]', !active);
                    button.setAttribute('aria-selected', active ? 'true' : 'false');
                });
                panels.forEach((panel) => panel.classList.toggle('hidden', panel.dataset.settingsPanel !== name));
                if (updateHash) history.replaceState(null, '', '#' + name);
            };
            buttons.forEach((button) => button.addEventListener('click', () => activate(button.dataset.settingsTab)));
            activate(tabs.includes(window.location.hash.slice(1)) ? window.location.hash.slice(1) : initial, false);
        })();
    </script>
@endcomponent
